@startuml

class GasStation {
  + ID : string
  + address : string
}

class FuelPump {
  + number : int
  + isSelfService : boolean
}

class Fuel {
  + name : string
  + octaneRating : int
}

class DailyPrice {
  + date : date
  + pricePerLiter : float
}

class FuelPurchase {
  + ID : string
  + litersDispensed : float
}

GasStation "1" *-- "0..12" FuelPump
FuelPump "*" -- "*" Fuel
GasStation "1" -- "*" DailyPrice
Fuel "1" -- "*" DailyPrice
GasStation "1" -- "*" FuelPurchase
FuelPump "1" -- "*" FuelPurchase
DailyPrice "1" -- "*" FuelPurchase

@enduml

